<?php require_once 'config/helpers.php'; if(is_customer()) redirect('customer/dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$pass=$_POST['password']??''; if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$phone===''||strlen($pass)<8){$error='Enter valid details. Password must be at least 8 characters.';}else{try{$st=$pdo->prepare('INSERT INTO customers(full_name,email,phone,password_hash) VALUES(?,?,?,?)');$st->execute([$name,$email,$phone,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['customer_id']=(int)$pdo->lastInsertId();$_SESSION['customer_name']=$name;flash('Your account was created. Welcome!');redirect('customer/dashboard.php');}catch(PDOException $e){$error='This email may already be registered.';}}} $page_title='Register';include 'includes/header.php'; ?>
<div class="form-wrap panel"><h1 class="section-title">Create Customer Account</h1><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div><label>Full name *</label><input name="full_name" required maxlength="120" value="<?= e($_POST['full_name']??'') ?>"></div><div><label>Email address *</label><input type="email" name="email" required></div><div><label>Phone number *</label><input name="phone" required maxlength="20"></div><div><label>Password * (minimum 8 characters)</label><input type="password" name="password" required minlength="8"></div><button>Create Account</button></form><p class="center">Already registered? <a href="login.php">Login</a></p></div><?php include 'includes/footer.php'; ?>
